{"output":"import React, { useState, useEffect, useRef } from 'react'
import { Card, CardHeader, CardTitle, CardContent } from '@/shadcn/ui/card'
import { Button } from '@/shadcn/ui/button'
import { Input } from '@/shadcn/ui/input'
import { 
  MessageCircle, 
  Send, 
  Bot, 
  User,
  FileText,
  Coins,
  Settings
} from 'lucide-react'
import { post } from '@/lib/api'

interface ChatMessage {
  id: string
  role: 'user' | 'assistant'
  content: string
  timestamp: string
}

interface ChatContext {
  capsule?: string
  policies?: string[]
  limits?: Record<string, any>
}

const MaintainerChat: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: '1',
      role: 'assistant',
      content: 'Привет! 👋 Я Мейнтейнер, ваш помощник по автоматизации бизнес-процессов. Что бы вы хотели автоматизировать?',
      timestamp: new Date().toISOString()
    }
  ])
  const [inputValue, setInputValue] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [context, setContext] = useState<ChatContext>({
    capsule: 'Feature Factory v1.0',
    policies: [
      'Бюджет токенов: 1M в день',
      'Очередь задач: FIFO',
      'Приоритеты: HIGH > MED > LOW'
    ],
    limits: {
      'Dev': { daily: 500000, used: 300000 },
      'QA': { daily: 300000, used: 150000 },
      'Scribe': { daily: 200000, used: 100000 }
    }
  })

  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  // Auto-scroll to bottom when messages change
  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  const handleSend = async () => {
    if (!inputValue.trim() || isLoading) return

    // Add user message
    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: inputValue,
      timestamp: new Date().toISOString()
    }

    setMessages(prev => [...prev, userMessage])
    setInputValue('')
    setIsLoading(true)

    try {
      // Call API to send message to maintainer
      const response = await post<any>('/chat/maintainer', {
        message: inputValue,
        context: {
          correlation_id: localStorage.getItem('correlationId') || crypto.randomUUID()
        }
      })

      // Add assistant response
      const assistantMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.data.response || 'Спасибо за ваш запрос. Я обработал ваше сообщение.',
        timestamp: new Date().toISOString()
      }

      setMessages(prev => [...prev, assistantMessage])
    } catch (error) {
      console.error('Error sending message:', error)

      // Add error message
      const errorMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: 'Извините, произошла ошибка при обработке вашего запроса. Пожалуйста, попробуйте еще раз.',
        timestamp: new Date().toISOString()
      }

      setMessages(prev => [...prev, errorMessage])
    } finally {
      setIsLoading(false)
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  return (
    <div className="flex h-[calc(100vh-200px)] gap-6">
      {/* Chat Messages */}
      <div className="flex-1 flex flex-col">
        <Card className="flex-1 flex flex-col">
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Чат с Maintainer</CardTitle>
            <MessageCircle className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent className="flex-1 flex flex-col p-0">
            <div className="flex-1 p-4 overflow-y-auto">
              <div className="space-y-4">
                {messages.map((message) => (
                  <div 
                    key={message.id} 
                    className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div 
                      className={`max-w-[80%] rounded-lg p-3 ${
                        message.role === 'user' 
                          ? 'bg-blue-500 text-white' 
                          : 'bg-gray-100 dark:bg-gray-700'
                      }`}
                    >
                      <div className="flex items-start gap-2">
                        {message.role === 'assistant' ? (
                          <Bot className="h-4 w-4 mt-0.5 flex-shrink-0" />
                        ) : (
                          <User className="h-4 w-4 mt-0.5 flex-shrink-0" />
                        )}
                        <div>
                          <p className="text-sm">{message.content}</p>
                          <p className={`text-xs mt-1 ${
                            message.role === 'user' 
                              ? 'text-blue-100' 
                              : 'text-gray-500 dark:text-gray-400'
                          }`}>
                            {new Date(message.timestamp).toLocaleTimeString()}
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
                {isLoading && (
                  <div className="flex justify-start">
                    <div className="bg-gray-100 dark:bg-gray-700 rounded-lg p-3">
                      <div className="flex items-center gap-2">
                        <Bot className="h-4 w-4 mt-0.5" />
                        <div className="flex space-x-1">
                          <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce"></div>
                          <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                          <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.4s' }}></div>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
","metadata":{"exit_code":0,"duration_seconds":0.0}}

{"output":"import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios'

// Detect debug from query param once at boot
const isDebug = typeof window !== 'undefined' && new URLSearchParams(window.location.search).get('debug') === '1'

// Create axios instance with default config
const apiClient: AxiosInstance = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || '/api/v1',
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
})

// Request interceptor to add X-Request-ID
apiClient.interceptors.request.use(
  (config) => {
    // Generate or get existing correlation ID
    const correlationId = localStorage.getItem('correlationId') || crypto.randomUUID()
    localStorage.setItem('correlationId', correlationId)

    // Add X-Request-ID header
    if (config.headers) {
      config.headers['X-Request-ID'] = correlationId
    }

    if (isDebug) {
      // Lightweight request log
      try {
        // eslint-disable-next-line no-console
        console.info('[FF/API] →', config.method?.toUpperCase(), config.baseURL + (config.url || ''))
      } catch {}
    }
    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

// Response interceptor to handle errors
apiClient.interceptors.response.use(
  (response: AxiosResponse) => {
    if (isDebug) {
      try {
        // eslint-disable-next-line no-console
        console.info('[FF/API] ←', response.status, response.config.baseURL + (response.config.url || ''))
      } catch {}
    }
    return response
  },
  (error) => {
    // Log error
    console.error('API Error:', error)

    // Return error for handling in components
    return Promise.reject(error)
  }
)

// Generic API call function
export const apiCall = async <T>(
  config: AxiosRequestConfig
): Promise<AxiosResponse<T>> => {
  return await apiClient(config)
}

// Helper functions for common HTTP methods
export const get = async <T>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return await apiCall<T>({ ...config, method: 'GET', url })
}

export const post = async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return await apiCall<T>({ ...config, method: 'POST', url, data })
}

export const put = async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return await apiCall<T>({ ...config, method: 'PUT', url, data })
}

export const del = async <T>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return await apiCall<T>({ ...config, method: 'DELETE', url })
}

export default apiClient
